"""Resource-constrained scheduler for the 42 zone-lifts."""
import numpy as np, itertools, random, math, json, sys, time
from numpy.lib.stride_tricks import sliding_window_view as swv
import model as M

T = 330
F = M.FACTS
ZLS = M.ZL_ORDER
ZIDX = {z: i for i, z in enumerate(ZLS)}
EPS = 1e-6

# conservative-modelling switches
CFG = dict(
    reshore_incl=1,      # count reshore in yard through POUR.f + 28 inclusive
    laydown_incl=1,      # count laydown through POUR.f inclusive
    egress_gap=0,        # extra idle days between consecutive stair-core shored intervals
    shore_incl=0,        # count shoring through STRK.f inclusive
)


def variants():
    out = []
    for c_off in (0, 1, 2):
        for g2 in (0, 1, 2):
            for g3 in (0, 1, 2):
                for g1 in (0, 1):
                    out.append((c_off, 0, g1, g2, g3, 0))
    out.sort(key=lambda v: (v[2] + v[3] + v[4] + v[5], v[0], v))
    return out


VARS = variants()


def pattern(f, v, cfg=CFG):
    """Return dict of activity -> (start, finish) relative to h (SHOR start)."""
    c_off, s_off, g1, g2, g3, g4 = v
    a = f.acts
    p = {}
    p['COL'] = (-1 - c_off, -c_off)
    p['SCAF'] = (-1 - s_off, -s_off)
    p['SHOR'] = (0, a['SHOR']['dur'])
    r0 = p['SHOR'][1] + g1
    p['RBAR'] = (r0, r0 + a['RBAR']['dur'])
    p0 = p['RBAR'][1] + g2
    p['POUR'] = (p0, p0 + a['POUR']['dur'])
    k0 = p['POUR'][1] + f.strike_days + g3
    p['STRK'] = (k0, k0 + 1)
    s0 = p['STRK'][1] + g4
    p['SCST'] = (s0, s0 + 1)
    return p


def profiles(f, v, cfg=CFG):
    p = pattern(f, v, cfg)
    o = min(s for s, e in p.values())
    pour_f = p['POUR'][1]
    end = max(max(e for s, e in p.values()), pour_f + M.FULL_DAYS + 1 + cfg['reshore_incl'])
    L = end - o
    crane = np.zeros(L); gang = np.zeros(L); shore = np.zeros(L); scaf = np.zeros(L); lay = np.zeros(L); egr = np.zeros(L)
    for t, (s, e) in p.items():
        d = e - s
        crane[s - o:e - o] += f.acts[t]['crane'] / d
        gang[s - o:e - o] += 1
    shore[p['SHOR'][0] - o:p['STRK'][1] + cfg['shore_incl'] - o] += f.area
    shore[p['STRK'][0] - o:pour_f + M.FULL_DAYS + cfg['reshore_incl'] - o] += M.RESHORE_FRAC * f.area
    scaf[p['SCAF'][0] - o:p['SCST'][1] - o] += f.face
    lay[p['SHOR'][0] - o:pour_f + cfg['laydown_incl'] - o] += f.laydown
    if f.stair_core:
        egr[p['SHOR'][0] - o:p['STRK'][1] + cfg['egress_gap'] - o] += 1
    return dict(o=o, L=L, crane=crane, gang=gang, shore=shore, scaf=scaf, lay=lay, egr=egr, pat=p)


CAPS = dict(crane=M.CRANE_H + EPS, gang=M.GANGS + EPS, shore=M.SHORE_STOCK + EPS,
            scaf=M.SCAF_STOCK + EPS, lay=M.LAYDOWN + EPS, egr=M.EGRESS_MAX + EPS)
RES = list(CAPS)

PROF = {}


def build_profiles(cfg=CFG):
    PROF.clear()
    for z in ZLS:
        PROF[z] = [profiles(F[z], v, cfg) for v in VARS]


build_profiles()


class State:
    def __init__(self):
        self.U = {r: np.zeros(T) for r in RES}
        self.sched = {}   # z -> (h, variant index)

    def add(self, z, h, vi):
        pr = PROF[z][vi]
        a = h + pr['o']
        for r in RES:
            self.U[r][a:a + pr['L']] += pr[r]
        self.sched[z] = (h, vi)


def earliest(state, z, vi, hmin):
    pr = PROF[z][vi]
    o, L = pr['o'], pr['L']
    lo = max(hmin, -o)
    if lo + o + L > T:
        return None
    ok = None
    for r in RES:
        prof = pr[r]
        if not prof.any():
            continue
        W = swv(state.U[r], L)[lo + o:]           # windows starting at lo+o ...
        feas = np.all(W + prof <= CAPS[r], axis=1)
        ok = feas if ok is None else (ok & feas)
    if ok is None:
        return lo
    idx = np.flatnonzero(ok)
    if len(idx) == 0:
        return None
    return lo + int(idx[0])


def lower_zl(z):
    f = F[z]
    li = M.LEVELS.index(f.level)
    if li == 0:
        return None
    return f'{M.LEVELS[li - 1]}-{f.zone}'


def finish_of(z, h, vi):
    p = PROF[z][vi]['pat']
    return h + p['SCST'][1]


def act_times(z, h, vi):
    p = PROF[z][vi]['pat']
    return {t: (h + s, h + e) for t, (s, e) in p.items()}


def repair(order):
    """ensure L2 < L3 < L4 within each zone by reassigning positions"""
    pos = {}
    for i, z in enumerate(order):
        pos.setdefault(F[z].zone, []).append(i)
    out = list(order)
    for zone, idxs in pos.items():
        zl_sorted = [f'{L}-{zone}' for L in M.LEVELS]
        for i, z in zip(sorted(idxs), zl_sorted):
            out[i] = z
    return out


def decode(order, diaphragm_aware=True):
    order = repair(order)
    st = State()
    times = {}
    for z in order:
        lz = lower_zl(z)
        rel = 0
        if lz is not None:
            rel = times[lz]['SCST'][1]
        best = None
        for vi, v in enumerate(VARS):
            c_off = v[0]
            hmin = rel + 1 + c_off
            h = earliest(st, z, vi, hmin)
            if h is None:
                continue
            fin = finish_of(z, h, vi)
            key = (fin, h, vi)
            if best is None or key < best[0]:
                best = (key, h, vi)
        if best is None:
            return None, None, None
        _, h, vi = best
        st.add(z, h, vi)
        times[z] = act_times(z, h, vi)
    return st, times, order


def lateral(times):
    """choose adjacent_diaphragm where an adjacent same-level slab reached early-strike age before SHOR."""
    res = {}
    for z in ZLS:
        f = F[z]
        shor_s = times[z]['SHOR'][0]
        best = None
        for az in f.adjacent:
            azl = f'{f.level}-{az}'
            fa = F[azl]
            ready = times[azl]['POUR'][1] + fa.strike_days
            if ready <= shor_s:
                slack = shor_s - ready
                if best is None or slack > best[1]:
                    best = (azl, slack, ready)
        res[z] = best
    return res


def objective(times, lat=None):
    if lat is None:
        lat = lateral(times)
    tot = 0.0
    for z in ZLS:
        fin = times[z]['SCST'][1]
        tot += M.DAY_COST * fin
        if lat[z] is None:
            tot += M.BRACING[z]['cost_units']
        if fin > M.DEADLINE:
            tot += 10000 * (fin - M.DEADLINE)
    return tot


def evaluate(order):
    st, times, order = decode(order)
    if times is None:
        return 1e12, None, order
    return objective(times), times, order


def initial_orders():
    bands = 'ABCDEFG'
    orders = []
    # level-major, band order
    o1 = sorted(ZLS, key=lambda z: (M.LEVELS.index(F[z].level), bands.index(F[z].band), F[z].zone))
    orders.append(o1)
    # diagonal wave: level index weighted
    for w in (2, 3, 4, 5):
        o = sorted(ZLS, key=lambda z: (M.LEVELS.index(F[z].level) * w + bands.index(F[z].band), F[z].zone))
        orders.append(o)
        o = sorted(ZLS, key=lambda z: (M.LEVELS.index(F[z].level) * w + (6 - bands.index(F[z].band)), F[z].zone))
        orders.append(o)
    # by area-days within level
    o = sorted(ZLS, key=lambda z: (M.LEVELS.index(F[z].level), F[z].area))
    orders.append(o)
    return orders


def anneal(order, iters=3000, T0=40.0, T1=1.0, seed=0, log=True):
    rng = random.Random(seed)
    cur_val, cur_times, cur = evaluate(order)
    best_val, best_times, best = cur_val, cur_times, cur
    n = len(cur)
    t0 = time.time()
    for it in range(iters):
        temp = T0 * (T1 / T0) ** (it / max(1, iters - 1))
        cand = list(cur)
        mv = rng.random()
        if mv < 0.4:
            i, j = rng.sample(range(n), 2)
            cand[i], cand[j] = cand[j], cand[i]
        elif mv < 0.8:
            i, j = rng.sample(range(n), 2)
            x = cand.pop(i); cand.insert(j, x)
        else:
            i = rng.randrange(n - 1)
            j = min(n, i + rng.randint(2, 6))
            seg = cand[i:j]; seg.reverse(); cand[i:j] = seg
        val, times, cand = evaluate(cand)
        if val <= cur_val or rng.random() < math.exp(-(val - cur_val) / temp):
            cur_val, cur_times, cur = val, times, cand
            if val < best_val:
                best_val, best_times, best = val, times, cand
        if log and it % 200 == 0:
            print(f'it {it} temp {temp:.2f} cur {cur_val:.0f} best {best_val:.0f} ({time.time()-t0:.0f}s)', flush=True)
    return best_val, best_times, best


if __name__ == '__main__':
    t = time.time()
    for o in initial_orders():
        val, times, oo = evaluate(o)
        mk = max(times[z]['SCST'][1] for z in ZLS) if times else None
        print(round(val), mk, round(time.time() - t, 2))

