slabs = {(r['level'], r['zone']): r for r in rd('model/slab_schedule.csv')}
mixes = {r['mix_id']: r for r in rd('catalogue/concrete_mix_schedule.csv')}
scat = {r['system']: r for r in rd('catalogue/scaffold_catalogue.csv')}
comps = {r['component']: r for r in rd('catalogue/scaffold_components.csv')}
duty = {r['duty_class']: r for r in rd('catalogue/scaffold_duty_classes.csv')}
shcat = {r['post_type']: r for r in rd('catalogue/shoring_catalogue.csv')}
