"""MILP large-neighbourhood search around an incumbent schedule (tight patterns)."""
import numpy as np, json, sys, time, random
from scipy.optimize import milp, LinearConstraint, Bounds
from scipy.sparse import coo_matrix
import model as M
import sched as S

ZLS = M.ZL_ORDER


def setup(gap):
    S.CFG['egress_gap'] = gap
    S.build_profiles(S.CFG)


def solve(windows, H=250, tl=120, verbose=False, diaphragm=True):
    """windows: z -> list of allowed h. Returns hs dict or None."""
    VI = 0
    prof = {z: S.PROF[z][VI] for z in ZLS}
    base = {z: prof[z]['pat']['SCST'][1] for z in ZLS}
    var = []; idx = {}
    for z in ZLS:
        for h in windows[z]:
            if h + prof[z]['o'] < 0 or h + base[z] > H:
                continue
            idx[(z, h)] = len(var); var.append((z, h))
    nzv = len(var)
    rows, cols, vals, lo, hi = [], [], [], [], []
    r = 0
    for z in ZLS:
        hs = [h for h in windows[z] if (z, h) in idx]
        for h in hs:
            rows.append(r); cols.append(idx[(z, h)]); vals.append(1.0)
        lo.append(1); hi.append(1); r += 1
    for res in ['crane', 'gang', 'shore', 'scaf', 'lay', 'egr']:
        cap = S.CAPS[res]
        contrib = {}
        for (z, h), j in idx.items():
            pr = prof[z]; P = pr[res]
            for k in np.flatnonzero(P):
                contrib.setdefault(h + pr['o'] + k, []).append((j, P[k]))
        for d, lst in contrib.items():
            if sum(a for _, a in lst) <= cap:
                continue
            for j, a in lst:
                rows.append(r); cols.append(j); vals.append(a)
            lo.append(-np.inf); hi.append(cap); r += 1
    # zone chain: h_up >= h_low + base_low + 1   (disaggregated)
    for z in ZLS:
        lz = S.lower_zl(z)
        if not lz:
            continue
        up = sorted(h for h in windows[z] if (z, h) in idx)
        low = sorted(h for h in windows[lz] if (lz, h) in idx)
        for t in up:
            ok = False
            for h in up:
                if h <= t:
                    rows.append(r); cols.append(idx[(z, h)]); vals.append(1.0)
            for h in low:
                if h <= t - base[lz] - 1:
                    rows.append(r); cols.append(idx[(lz, h)]); vals.append(-1.0)
            lo.append(-np.inf); hi.append(0); r += 1
    c = np.array([M.DAY_COST * (h + base[z]) for z, h in var], dtype=float)
    nvar = nzv
    # optional diaphragm variables: y_z = 1 -> no bracing cost; requires an adjacent pour ready by SHOR start
    ycols = {}
    if diaphragm:
        extra_c = []
        for z in ZLS:
            f = M.FACTS[z]
            adj = [f'{f.level}-{a}' for a in f.adjacent]
            ycols[z] = nvar; nvar += 1
            extra_c.append(-M.BRACING[z]['cost_units'])
            # for each t (SHOR start = h): y_z + x_{z,h} - sum_{a,h': ready(a,h') <= h} x_{a,h'} <= 1
            zh = sorted(h for h in windows[z] if (z, h) in idx)
            for t in zh:
                rows.append(r); cols.append(ycols[z]); vals.append(1.0)
                rows.append(r); cols.append(idx[(z, t)]); vals.append(1.0)
                for a in adj:
                    fa = M.FACTS[a]
                    pa = prof[a]['pat']
                    for h2 in windows[a]:
                        if (a, h2) in idx and h2 + pa['POUR'][1] + fa.strike_days <= t:
                            rows.append(r); cols.append(idx[(a, h2)]); vals.append(-1.0)
                lo.append(-np.inf); hi.append(1); r += 1
        c = np.concatenate([c, np.array(extra_c)])
    A = coo_matrix((vals, (rows, cols)), shape=(r, nvar)).tocsr()
    t0 = time.time()
    res = milp(c, constraints=LinearConstraint(A, np.array(lo), np.array(hi)), integrality=np.ones(nvar),
               bounds=Bounds(0, 1), options=dict(time_limit=tl, disp=verbose, mip_rel_gap=1e-6))
    if res.x is None:
        return None, None, time.time() - t0
    hs = {}
    for j in np.flatnonzero(res.x[:nzv] > 0.5):
        z, h = var[j]; hs[z] = h
    return hs, res, time.time() - t0


def times_from(hs):
    return {z: S.act_times(z, hs[z], 0) for z in ZLS}


def hs_from_times(times):
    return {z: times[z]['SHOR'][0] for z in ZLS}


def total(hs):
    t = times_from(hs)
    return S.objective(t), t


def is_default(times):
    for z in ZLS:
        tz = times[z]; f = M.FACTS[z]
        if (tz['COL'][0] != tz['SHOR'][0] - 1 or tz['SCAF'][0] != tz['SHOR'][0] - 1 or
                tz['RBAR'][0] != tz['SHOR'][1] or tz['POUR'][0] != tz['RBAR'][1] or
                tz['STRK'][0] != tz['POUR'][1] + f.strike_days or tz['SCST'][0] != tz['STRK'][1]):
            return False
    return True


def feasible(hs):
    st = S.State()
    for z in sorted(ZLS, key=lambda z: hs[z]):
        st.add(z, hs[z], 0)
    A = st.A
    if (A > S.CAPV + 1e-9).any():
        return False
    for z in ZLS:
        lz = S.lower_zl(z)
        if lz and hs[z] - 1 < hs[lz] + S.PROF[lz][0]['pat']['SCST'][1]:
            return False
    return True


if __name__ == '__main__':
    args = dict(a.split('=') for a in sys.argv[1:])
    setup(int(args.get('gap', 1)))
    d = json.load(open(args['start']))
    times = {z: {t: tuple(v) for t, v in d['times'][z].items()} for z in ZLS}
    assert is_default(times), 'start must use the default pattern'
    hs = hs_from_times(times)
    assert feasible(hs)
    best_val, _ = total(hs)
    print('start', best_val, flush=True)
    W = int(args.get('W', 6)); iters = int(args.get('iters', 30)); tl = float(args.get('tl', 60))
    seed = int(args.get('seed', 0)); rng = random.Random(seed)
    out = args.get('out', 'lns.json')
    for it in range(iters):
        mode = it % 3
        windows = {}
        if mode == 0:       # uniform window
            for z in ZLS:
                windows[z] = list(range(hs[z] - W, hs[z] + W + 1))
        else:               # free a random subset widely, rest tight
            free = set(rng.sample(ZLS, int(args.get('k', 10))))
            for z in ZLS:
                w = 3 * W if z in free else 2
